import ashleyseotheme from '@avatune/ashley-seo-theme/angular';
import fatinversetheme from '@avatune/fatin-verse-theme/angular';
import kutetheme from '@avatune/kyute-theme/angular';
import micahtheme from '@avatune/micah-theme/angular';
import miniavstheme from '@avatune/miniavs-theme/angular';
import nevmstastheme from '@avatune/nevmstas-theme/angular';
import pacovqzztheme from '@avatune/pacovqzz-theme/angular';
import pawelolekmantheme from '@avatune/pawel-olek-man-theme/angular';
import pawelolekwomantheme from '@avatune/pawel-olek-woman-theme/angular';
import yanliutheme from '@avatune/yanliu-theme/angular';
import { Avatar } from '@avatune/angular';
const meta = {
    title: 'Avatar',
    component: Avatar,
    parameters: { layout: 'centered' },
    tags: ['autodocs'],
};
export default meta;
const getArgTypes = (theme) => {
    const argTypes = {
        inputSize: { control: { type: 'range', min: 100, max: 800, step: 50 } },
    };
    const colorPalettes = theme.colorPalettes;
    for (const [category, items] of Object.entries(theme)) {
        const excludeCategories = ['style', 'predictorMappings', 'colorPalettes', 'connectedColors'];
        if (excludeCategories.includes(category))
            continue;
        const presetColors = colorPalettes[category];
        argTypes[`${category}Color`] = { control: { type: 'color', presetColors } };
        argTypes[category] = {
            control: { type: 'select' },
            options: Object.keys(items),
        };
    }
    argTypes.backgroundColor = { control: { type: 'color', presetColors: colorPalettes.background } };
    return argTypes;
};
export const AshleySeo = {
    argTypes: getArgTypes(ashleyseotheme),
    render: () => ({
        props: { theme: ashleyseotheme, inputSize: 300 },
    }),
};
export const FatinVerse = {
    argTypes: getArgTypes(fatinversetheme),
    render: () => ({
        props: { theme: fatinversetheme, inputSize: 300 },
    }),
};
export const Kyute = {
    argTypes: getArgTypes(kutetheme),
    render: () => ({
        props: { theme: kutetheme, inputSize: 300 },
    }),
};
export const Micah = {
    argTypes: getArgTypes(micahtheme),
    render: () => ({
        props: { theme: micahtheme, inputSize: 300 },
    }),
};
export const Miniavs = {
    argTypes: getArgTypes(miniavstheme),
    render: () => ({
        props: { theme: miniavstheme, inputSize: 300 },
    }),
};
export const Nevmstas = {
    argTypes: getArgTypes(nevmstastheme),
    render: () => ({
        props: { theme: nevmstastheme, inputSize: 300 },
    }),
};
export const Pacovqzz = {
    argTypes: getArgTypes(pacovqzztheme),
    render: () => ({
        props: { theme: pacovqzztheme, inputSize: 300 },
    }),
};
export const PawelOlekMan = {
    argTypes: getArgTypes(pawelolekmantheme),
    render: () => ({
        props: { theme: pawelolekmantheme, inputSize: 300 },
    }),
};
export const PawelOlekWoman = {
    argTypes: getArgTypes(pawelolekwomantheme),
    render: () => ({
        props: { theme: pawelolekwomantheme, inputSize: 300 },
    }),
};
export const Yanliu = {
    argTypes: getArgTypes(yanliutheme),
    render: () => ({
        props: { theme: yanliutheme, inputSize: 300 },
    }),
};
